insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense', 'A sense is a biological system used by an organism for sensation, the process of gathering information about the surroundings through the detection of stimuli. During sensation, sense organs collect various stimuli (such as a sound or smell) for transduction, meaning transformation into a form that can be understood by the brain. Sensation and perception are fundamental to nearly every aspect of an organism''s cognition, behavior and thought. Although, in some cultures, five human senses were traditionally identified as such (namely sight, smell, touch, taste, and hearing), many more are now recognized. Senses used by non-human organisms are even greater in variety and number. In organisms, a sensory organ consists of a group of interrelated sensory cells that respond to a specific type of physical stimulus. Via cranial and spinal nerves (nerves of the central and peripheral nervous systems that relay sensory information to and from the brain and body), the different types of sensory receptor cells (such as mechanoreceptors, photoreceptors, chemoreceptors, thermoreceptors) in sensory organs transduct sensory information from these organs towards the central nervous system, finally arriving at the sensory cortices in the brain, where sensory signals are processed and interpreted (perceived).', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'A sense is a biological system used by an organism for sensation, the process of gathering information about the surroundings through the detection of stimuli. During sensation, sense organs collect various stimuli (such as a sound or smell) for transduction, meaning transformation into a form that can be understood by the brain. Sensation and perception are fundamental to nearly every aspect of an organism''s cognition, behavior and thought. Although, in some cultures, five human senses were traditionally identified as such (namely sight, smell, touch, taste, and hearing), many more are now recognized. Senses used by non-human organisms are even greater in variety and number. In organisms, a sensory organ consists of a group of interrelated sensory cells that respond to a specific type of physical stimulus. Via cranial and spinal nerves (nerves of the central and peripheral nervous systems that relay sensory information to and from the brain and body), the different types of sensory receptor cells (such as mechanoreceptors, photoreceptors, chemoreceptors, thermoreceptors) in sensory organs transduct sensory information from these organs towards the central nervous system, finally arriving at the sensory cortices in the brain, where sensory signals are processed and interpreted (perceived).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense', 'Sensory systems, or senses, are often divided into external (exteroception) and internal (interoception) sensory systems. Human external senses are based on the sensory organs of the eyes, ears, skin, nose, and mouth. Internal sensation detects stimuli from internal organs and tissues. Internal senses possessed by humans include spatial orientation, proprioception (body position) and nociception (pain). Further internal senses lead to signals such as hunger, thirst, suffocation, and nausea, or different involuntary behaviors, such as vomiting. Some animals are able to detect electrical and magnetic fields, air moisture, or polarized light, while others sense and perceive through alternative systems, such as echolocation. Sensory modalities or sub modalities are different ways sensory information is encoded or transduced. Multimodality integrates different senses into one unified perceptual experience. For example, information from one sense has the potential to influence how information from another is perceived. Sensation and perception are studied by a variety of related fields, most notably psychophysics, neurobiology, cognitive psychology, and cognitive science.', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Sensory systems, or senses, are often divided into external (exteroception) and internal (interoception) sensory systems. Human external senses are based on the sensory organs of the eyes, ears, skin, nose, and mouth. Internal sensation detects stimuli from internal organs and tissues. Internal senses possessed by humans include spatial orientation, proprioception (body position) and nociception (pain). Further internal senses lead to signals such as hunger, thirst, suffocation, and nausea, or different involuntary behaviors, such as vomiting. Some animals are able to detect electrical and magnetic fields, air moisture, or polarized light, while others sense and perceive through alternative systems, such as echolocation. Sensory modalities or sub modalities are different ways sensory information is encoded or transduced. Multimodality integrates different senses into one unified perceptual experience. For example, information from one sense has the potential to influence how information from another is perceived. Sensation and perception are studied by a variety of related fields, most notably psychophysics, neurobiology, cognitive psychology, and cognitive science.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense: Sensory organs', 'Sensory organs are organs that detect and transduce stimuli. Humans have sensory organs (i.e. eyes, ears, skin, nose, and mouth) that correspond to a respective visual (vision), auditory (hearing) and vestibular (balance), somatosensory (touch), olfactory (smell), and gustatory systems (taste). Internal sensation, or interoception, detects stimuli from internal organs and tissues. Humans have various internal sensory and perceptual systems, such as nociception, proprioception and equilibrioception. Chemoreception and osmoreception based sensory systems lead to various perceptions, such as hunger, thirst, suffocation, and nausea. Nonhuman animals experience sensation and perception, with varying levels of similarity to and difference from humans and other animal species. For example, other mammals in general have a stronger sense of smell than humans. Some animal species lack one or more human sensory system analogues and some have sensory systems that are not found in humans, while others process and interpret the same sensory information in very different ways. For example, some animals are able to detect electrical fields and magnetic fields, air moisture, or polarized light. Others sense and perceive through alternative systems such as echolocation. Recent theory suggests that plants and artificial agents such as robots may be able to detect and interpret environmental information in an analogous manner to animals.', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Sensory organs are organs that detect and transduce stimuli. Humans have sensory organs (i.e. eyes, ears, skin, nose, and mouth) that correspond to a respective visual (vision), auditory (hearing) and vestibular (balance), somatosensory (touch), olfactory (smell), and gustatory systems (taste). Internal sensation, or interoception, detects stimuli from internal organs and tissues. Humans have various internal sensory and perceptual systems, such as nociception, proprioception and equilibrioception. Chemoreception and osmoreception based sensory systems lead to various perceptions, such as hunger, thirst, suffocation, and nausea. Nonhuman animals experience sensation and perception, with varying levels of similarity to and difference from humans and other animal species. For example, other mammals in general have a stronger sense of smell than humans. Some animal species lack one or more human sensory system analogues and some have sensory systems that are not found in humans, while others process and interpret the same sensory information in very different ways. For example, some animals are able to detect electrical fields and magnetic fields, air moisture, or polarized light. Others sense and perceive through alternative systems such as echolocation. Recent theory suggests that plants and artificial agents such as robots may be able to detect and interpret environmental information in an analogous manner to animals.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense: Sensory modalities', 'Sensory modality refers to the way that information is encoded, which is similar to the idea of transduction. The main sensory modalities can be described on the basis of how each is transduced. Listing all the different sensory modalities, which can number as many as 17, involves separating the major senses into more specific categories, or submodalities, of the larger sense. An individual sensory modality represents the sensation of a specific type of stimulus. For example, the general sensation and perception of touch, which is known as somatosensation, can be separated into light pressure, deep pressure, vibration, itch, pain, temperature, or hair movement, while the general sensation and perception of taste can be separated into submodalities of sweet, salty, sour, bitter, spicy, and umami, all of which are based on different chemicals binding to sensory neurons.', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Sensory modality refers to the way that information is encoded, which is similar to the idea of transduction. The main sensory modalities can be described on the basis of how each is transduced. Listing all the different sensory modalities, which can number as many as 17, involves separating the major senses into more specific categories, or submodalities, of the larger sense. An individual sensory modality represents the sensation of a specific type of stimulus. For example, the general sensation and perception of touch, which is known as somatosensation, can be separated into light pressure, deep pressure, vibration, itch, pain, temperature, or hair movement, while the general sensation and perception of taste can be separated into submodalities of sweet, salty, sour, bitter, spicy, and umami, all of which are based on different chemicals binding to sensory neurons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense: Receptors', 'Sensory receptors are the cells or structures that detect sensations. Stimuli in the environment activate specialized receptor cells in the peripheral nervous system. During transduction, physical stimulus is converted into action potential by receptors and transmitted towards the central nervous system for processing. Different types of stimuli are sensed by different types of receptor cells. Receptor cells can be classified into types on the basis of three different criteria: cell type, position, and function. Receptors can be classified structurally on the basis of cell type and their position in relation to stimuli they sense. Receptors can further be classified functionally on the basis of the transduction of stimuli, or how the mechanical stimulus, light, or chemical changed the cell membrane potential.', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Sensory receptors are the cells or structures that detect sensations. Stimuli in the environment activate specialized receptor cells in the peripheral nervous system. During transduction, physical stimulus is converted into action potential by receptors and transmitted towards the central nervous system for processing. Different types of stimuli are sensed by different types of receptor cells. Receptor cells can be classified into types on the basis of three different criteria: cell type, position, and function. Receptors can be classified structurally on the basis of cell type and their position in relation to stimuli they sense. Receptors can further be classified functionally on the basis of the transduction of stimuli, or how the mechanical stimulus, light, or chemical changed the cell membrane potential.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense: Location', 'One way to classify receptors is based on their location relative to the stimuli. An exteroceptor is a receptor that is located near a stimulus of the external environment, such as the somatosensory receptors that are located in the skin. An interoceptor is one that interprets stimuli from internal organs and tissues, such as the receptors that sense the increase in blood pressure in the aorta or carotid sinus.', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'One way to classify receptors is based on their location relative to the stimuli. An exteroceptor is a receptor that is located near a stimulus of the external environment, such as the somatosensory receptors that are located in the skin. An interoceptor is one that interprets stimuli from internal organs and tissues, such as the receptors that sense the increase in blood pressure in the aorta or carotid sinus.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense: Cell type', 'The cells that interpret information about the environment can be either (1) a neuron that has a free nerve ending, with dendrites embedded in tissue that would receive a sensation; (2) a neuron that has an encapsulated ending in which the sensory nerve endings are encapsulated in connective tissue that enhances their sensitivity; or (3) a specialized receptor cell, which has distinct structural components that interpret a specific type of stimulus. The pain and temperature receptors in the dermis of the skin are examples of neurons that have free nerve endings (1). Also located in the dermis of the skin are lamellated corpuscles, neurons with encapsulated nerve endings that respond to pressure and touch (2). The cells in the retina that respond to light stimuli are an example of a specialized receptor (3), a photoreceptor.', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The cells that interpret information about the environment can be either (1) a neuron that has a free nerve ending, with dendrites embedded in tissue that would receive a sensation; (2) a neuron that has an encapsulated ending in which the sensory nerve endings are encapsulated in connective tissue that enhances their sensitivity; or (3) a specialized receptor cell, which has distinct structural components that interpret a specific type of stimulus. The pain and temperature receptors in the dermis of the skin are examples of neurons that have free nerve endings (1). Also located in the dermis of the skin are lamellated corpuscles, neurons with encapsulated nerve endings that respond to pressure and touch (2). The cells in the retina that respond to light stimuli are an example of a specialized receptor (3), a photoreceptor.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Sense: Cell type', 'A transmembrane protein receptor is a protein in the cell membrane that mediates a physiological change in a neuron, most often through the opening of ion channels or changes in the cell signaling processes. Transmembrane receptors are activated by chemicals called ligands. For example, a molecule in food can serve as a ligand for taste receptors. Other transmembrane proteins, which are not accurately called receptors, are sensitive to mechanical or thermal changes. Physical changes in these proteins increase ion flow across the membrane, and can generate an action potential or a graded potential in the sensory neurons.', 'Wikipedia: Sense', 'https://en.wikipedia.org/w/index.php?title=Sense&oldid=1380569917', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'A transmembrane protein receptor is a protein in the cell membrane that mediates a physiological change in a neuron, most often through the opening of ion channels or changes in the cell signaling processes. Transmembrane receptors are activated by chemicals called ligands. For example, a molecule in food can serve as a ligand for taste receptors. Other transmembrane proteins, which are not accurately called receptors, are sensitive to mechanical or thermal changes. Physical changes in these proteins increase ion flow across the membrane, and can generate an action potential or a graded potential in the sensory neurons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold', 'In neuroscience and psychophysics, an absolute threshold was originally defined as the lowest level of a stimulus – light, sound, touch, etc. – that an organism could detect. Under the influence of signal detection theory, absolute threshold has been redefined as the level at which a stimulus will be detected a specified percentage (often 50%) of the time. The absolute threshold can be influenced by several different factors, such as the subject''s motivations and expectations, cognitive processes, and whether the subject is adapted to the stimulus. The absolute threshold can be compared to the difference threshold, which is the measure of how different two stimuli must be for the subject to notice that they are not the same.', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In neuroscience and psychophysics, an absolute threshold was originally defined as the lowest level of a stimulus – light, sound, touch, etc. – that an organism could detect. Under the influence of signal detection theory, absolute threshold has been redefined as the level at which a stimulus will be detected a specified percentage (often 50%) of the time. The absolute threshold can be influenced by several different factors, such as the subject''s motivations and expectations, cognitive processes, and whether the subject is adapted to the stimulus. The absolute threshold can be compared to the difference threshold, which is the measure of how different two stimuli must be for the subject to notice that they are not the same.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold: Vision', 'A landmark 1942 experiment by Hecht, Shlaer, and Pirenne assessed the absolute threshold for vision. They tried to measure the minimum number of photons the human eye can detect 60% of the time, using the following controls: Dark adaptation – the participants were completely dark adapted (a process lasting forty minutes) to optimise their visual sensitivity. Location – the stimulus was presented to an area of the right eye where there is a high density of rod cells, 20 degrees to the left of the point of focus (i.e. 20 degrees to the right of the fovea). Roughly this degree of eccentricity (about 20 degrees) has the highest rod density across the whole retina. However, the corresponding location on the right retina, 20 degrees to the left, is very near the blind spot. Stimulus size – the stimulus had a diameter of 10 minutes of arc (1 minute = 1/60th of a degree). Although not explicitly mentioned in the original research paper, this ensured that the light stimulus fell only on rod cells connected to the same nerve fibre (this is called the area of spatial summation). Wavelength – the stimulus wavelength matched the maximum sensitivity of rod cells (510 nm).', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'A landmark 1942 experiment by Hecht, Shlaer, and Pirenne assessed the absolute threshold for vision. They tried to measure the minimum number of photons the human eye can detect 60% of the time, using the following controls: Dark adaptation – the participants were completely dark adapted (a process lasting forty minutes) to optimise their visual sensitivity. Location – the stimulus was presented to an area of the right eye where there is a high density of rod cells, 20 degrees to the left of the point of focus (i.e. 20 degrees to the right of the fovea). Roughly this degree of eccentricity (about 20 degrees) has the highest rod density across the whole retina. However, the corresponding location on the right retina, 20 degrees to the left, is very near the blind spot. Stimulus size – the stimulus had a diameter of 10 minutes of arc (1 minute = 1/60th of a degree). Although not explicitly mentioned in the original research paper, this ensured that the light stimulus fell only on rod cells connected to the same nerve fibre (this is called the area of spatial summation). Wavelength – the stimulus wavelength matched the maximum sensitivity of rod cells (510 nm).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold: Vision', 'The researchers found that the emission of only 5–14 photons could elicit visual experience. However, only about half of these entered the retina, due to reflection (from the cornea), absorption, and other factors relating to transmittance of the ocular media. The researchers estimated that 5 to 14 of the estimated 500 rods in the test area would each absorb one photon, with a 4% chance that one rod would absorb two photons. A second absolute threshold for vision involves the minimum photon flux (photons per second per unit area). In this case the light covers a wide field over an extended period of time instead of being concentrated on one spot on the retina in a short burst. Knowing the pupil diameter and the wavelength of the light, the result can be described in terms of luminance (~0.000001 candela per square meter or 10−6 cd/m2) or retinal illuminance (~0.00002 Trolands). By including estimates for the probability of an average photon being absorbed by an average rod cell, the threshold stimulation for the rods is approximately one photon absorption per second per 5000 rods.', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The researchers found that the emission of only 5–14 photons could elicit visual experience. However, only about half of these entered the retina, due to reflection (from the cornea), absorption, and other factors relating to transmittance of the ocular media. The researchers estimated that 5 to 14 of the estimated 500 rods in the test area would each absorb one photon, with a 4% chance that one rod would absorb two photons. A second absolute threshold for vision involves the minimum photon flux (photons per second per unit area). In this case the light covers a wide field over an extended period of time instead of being concentrated on one spot on the retina in a short burst. Knowing the pupil diameter and the wavelength of the light, the result can be described in terms of luminance (~0.000001 candela per square meter or 10−6 cd/m2) or retinal illuminance (~0.00002 Trolands). By including estimates for the probability of an average photon being absorbed by an average rod cell, the threshold stimulation for the rods is approximately one photon absorption per second per 5000 rods.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold: Vision', 'In terms of total absolute power sensitivity, Denton and Pirenne in The Journal of Physiology in 1954 found that for diffuse, extended sources i.e. a relatively large (~ 45-degree wide source, as viewed by the subject) frosted glass aperture, and a long (5 second) observation and decision time, the human eye could begin to reliably distinguish the lit from unlit glass at a power level of approximately 7.6 × 10−14 watts / steradian-cm2 at the eye for green (510 nm) light. This power level was dependent on the wavelength of the light used according to the usual luminosity curve. For white light, the absolute sensitivity found was 5.9 × 10−14 watts / steradian-cm2. This base sensitivity varied only about 0.03 log steps between monocular (one-eyed) or binocular (two-eyed) vision.', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In terms of total absolute power sensitivity, Denton and Pirenne in The Journal of Physiology in 1954 found that for diffuse, extended sources i.e. a relatively large (~ 45-degree wide source, as viewed by the subject) frosted glass aperture, and a long (5 second) observation and decision time, the human eye could begin to reliably distinguish the lit from unlit glass at a power level of approximately 7.6 × 10−14 watts / steradian-cm2 at the eye for green (510 nm) light. This power level was dependent on the wavelength of the light used according to the usual luminosity curve. For white light, the absolute sensitivity found was 5.9 × 10−14 watts / steradian-cm2. This base sensitivity varied only about 0.03 log steps between monocular (one-eyed) or binocular (two-eyed) vision.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold: Vision', 'In 1972 Sakitt conducted an experiment that combined elements of signal detection and threshold theory. Two key elements of the study were a high tolerance for false positives and a multiple-choice option on deciding whether or not a light was seen. In the classic studies described above, the tolerance for false positives was so low that threshold was biased upward. Based on statistical analysis of a large number of trials, 6 photons each absorbed by one rod near-simultaneously looked "very bright", 5 photons looked "bright", 4 photons "a moderate light", 3 photons "a dim light". Two observers were able to see 2 photons as "slightly doubtful if a light was seen." One observer saw a single photon as "very doubtful if a light was seen." Zero photons were seen as "did not see anything".', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In 1972 Sakitt conducted an experiment that combined elements of signal detection and threshold theory. Two key elements of the study were a high tolerance for false positives and a multiple-choice option on deciding whether or not a light was seen. In the classic studies described above, the tolerance for false positives was so low that threshold was biased upward. Based on statistical analysis of a large number of trials, 6 photons each absorbed by one rod near-simultaneously looked "very bright", 5 photons looked "bright", 4 photons "a moderate light", 3 photons "a dim light". Two observers were able to see 2 photons as "slightly doubtful if a light was seen." One observer saw a single photon as "very doubtful if a light was seen." Zero photons were seen as "did not see anything".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold: Hearing', 'The absolute threshold of hearing is the minimum sound level of a pure tone that an average ear with normal hearing can hear with no other sound present. The absolute threshold relates to the sound that can just be heard by the organism. The threshold of hearing is generally reported as the RMS sound pressure of 20 μPa (micropascals) = 2×10−5 pascal (Pa). It is approximately the quietest sound a young human with undamaged hearing can detect at 1,000 Hz. The threshold of hearing is frequency dependent and it has been shown that the ear''s sensitivity is best at frequencies between 1 kHz and 5 kHz. Humans typically have a lower hearing threshold for their own names. Dennis P. Carmody and Michael Lewis studied this phenomenon in 2006 and found that brain regions respond to the person''s name differently than they do to a random name.', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The absolute threshold of hearing is the minimum sound level of a pure tone that an average ear with normal hearing can hear with no other sound present. The absolute threshold relates to the sound that can just be heard by the organism. The threshold of hearing is generally reported as the RMS sound pressure of 20 μPa (micropascals) = 2×10−5 pascal (Pa). It is approximately the quietest sound a young human with undamaged hearing can detect at 1,000 Hz. The threshold of hearing is frequency dependent and it has been shown that the ear''s sensitivity is best at frequencies between 1 kHz and 5 kHz. Humans typically have a lower hearing threshold for their own names. Dennis P. Carmody and Michael Lewis studied this phenomenon in 2006 and found that brain regions respond to the person''s name differently than they do to a random name.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold: Odor', 'The odor detection threshold is the lowest concentration of a certain odor compound that is perceivable by the human sense of smell. The threshold of a chemical compound is determined in part by its shape, polarity, partial charges and molecular mass. The olfactory mechanisms responsible for each compound''s detection threshold is not well understood; thus these thresholds cannot yet be accurately predicted. Rather, they must be measured through extensive tests using human subjects in laboratory settings.', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The odor detection threshold is the lowest concentration of a certain odor compound that is perceivable by the human sense of smell. The threshold of a chemical compound is determined in part by its shape, polarity, partial charges and molecular mass. The olfactory mechanisms responsible for each compound''s detection threshold is not well understood; thus these thresholds cannot yet be accurately predicted. Rather, they must be measured through extensive tests using human subjects in laboratory settings.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Absolute threshold: Touch', 'According to a 1962 study done by Galanter, the absolute threshold for touch is described as a bee''s wing dropped onto a person''s cheek from one centimeter (0.4 inches) away. Different parts of the body are more sensitive to touch, so this varies from one body part to the next (20). In 1974, Ulf Lindblom studied how the speed of a stimulus affects absolute threshold. A WaveTek stimulator was used to measure absolute threshold of touch by "tapping" a participant''s finger pad with a 2 mm diameter probe. Lindblom found that on average, there was a 27% difference in threshold level between slow and fast mechanical pulses on a participant''s finger pad. The threshold for rapid pulses was 5 μm, and 80 μm for slow pulses. Lindblom''s study shows that humans are more sensitive to fast stimulation than slow stimulation, at least for touch. As people age, the absolute threshold for touch becomes larger, especially after age 65. In general, women have a lower absolute threshold and are more sensitive to touch than men. However, it also seems to vary from person to person. Even individuals experience long-term variation within their own absolute threshold for touch. This could potentially affect how sensory disorders are evaluated by medical professionals.', 'Wikipedia: Absolute threshold', 'https://en.wikipedia.org/w/index.php?title=Absolute_threshold&oldid=1373852133', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'According to a 1962 study done by Galanter, the absolute threshold for touch is described as a bee''s wing dropped onto a person''s cheek from one centimeter (0.4 inches) away. Different parts of the body are more sensitive to touch, so this varies from one body part to the next (20). In 1974, Ulf Lindblom studied how the speed of a stimulus affects absolute threshold. A WaveTek stimulator was used to measure absolute threshold of touch by "tapping" a participant''s finger pad with a 2 mm diameter probe. Lindblom found that on average, there was a 27% difference in threshold level between slow and fast mechanical pulses on a participant''s finger pad. The threshold for rapid pulses was 5 μm, and 80 μm for slow pulses. Lindblom''s study shows that humans are more sensitive to fast stimulation than slow stimulation, at least for touch. As people age, the absolute threshold for touch becomes larger, especially after age 65. In general, women have a lower absolute threshold and are more sensitive to touch than men. However, it also seems to vary from person to person. Even individuals experience long-term variation within their own absolute threshold for touch. This could potentially affect how sensory disorders are evaluated by medical professionals.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law', 'The Weber–Fechner laws are two related scientific laws in the field of psychophysics, known as Weber''s law and Fechner''s law. Both relate to human perception, more specifically the relation between the actual change in a physical stimulus and the perceived change. This includes stimuli to all senses: vision, hearing, taste, touch, and smell. Ernst Heinrich Weber states that "the minimum increase of stimulus which will produce a perceptible increase of sensation is proportional to the pre-existent stimulus," while Gustav Fechner''s law is an inference from Weber''s law (with additional assumptions) which states that the intensity of our sensation increases as the logarithm of an increase in energy rather than as rapidly as the increase.', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The Weber–Fechner laws are two related scientific laws in the field of psychophysics, known as Weber''s law and Fechner''s law. Both relate to human perception, more specifically the relation between the actual change in a physical stimulus and the perceived change. This includes stimuli to all senses: vision, hearing, taste, touch, and smell. Ernst Heinrich Weber states that "the minimum increase of stimulus which will produce a perceptible increase of sensation is proportional to the pre-existent stimulus," while Gustav Fechner''s law is an inference from Weber''s law (with additional assumptions) which states that the intensity of our sensation increases as the logarithm of an increase in energy rather than as rapidly as the increase.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law: History and formulation of the laws', 'Both Weber''s law and Fechner''s law were formulated by Gustav Theodor Fechner (1801–1887). They were first published in 1860 in the work Elemente der Psychophysik (Elements of Psychophysics). This publication was the first work ever in this field, and where Fechner coined the term psychophysics to describe the interdisciplinary study of how humans perceive physical magnitudes. He made the claim that "...psycho-physics is an exact doctrine of the relation of function or dependence between body and soul."', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Both Weber''s law and Fechner''s law were formulated by Gustav Theodor Fechner (1801–1887). They were first published in 1860 in the work Elemente der Psychophysik (Elements of Psychophysics). This publication was the first work ever in this field, and where Fechner coined the term psychophysics to describe the interdisciplinary study of how humans perceive physical magnitudes. He made the claim that "...psycho-physics is an exact doctrine of the relation of function or dependence between body and soul."');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law: Weber''s law', 'Ernst Heinrich Weber (1795–1878) was one of the first persons to approach the study of the human response to a physical stimulus in a quantitative fashion. Fechner was a student of Weber and named his first law in honor of his mentor, since it was Weber who had conducted the experiments needed to formulate the law.', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Ernst Heinrich Weber (1795–1878) was one of the first persons to approach the study of the human response to a physical stimulus in a quantitative fashion. Fechner was a student of Weber and named his first law in honor of his mentor, since it was Weber who had conducted the experiments needed to formulate the law.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law: Weber''s law', 'In sensation and contrast, change is defined as "contrast over time". The senses detect the change; in Weber''s law, specifically, it is relative change, not absolute change, which is detected. In Weber''s law, to notice a change in stimulus (e.g. brightness or weight), the change must be constant proportion of the original stimulus. Weber''s law states that just noticeable difference is proportional to the magnitude of the initial stimulus. The brain is a percentage of change detector. The differential threshold is the smallest difference needed to differentiate two stimuli for each sense has been studied by using similarly methods to signal detection. For instance, holding an object that weighs 1,2,10, and 11lbs. If one were to hold the lightest object (1lb), and then swap out that object for the 2lb object, one could easily tell that the second object is heavier than the first. There is a 100% weight increase from the first object to the second. However, it becomes more difficult when the difference is a smaller percentage of the initial object''s weight. For example, if one were to hold the 10lb object, and then swap it out and hold the 11lb object, it would be difficult for one to tell which of the two is heavier, because there is only a 10% increase from the first to the second object. This demonstrates that bigger stimuli require a larger difference in order to be noticed. This is Weber''s Law.', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In sensation and contrast, change is defined as "contrast over time". The senses detect the change; in Weber''s law, specifically, it is relative change, not absolute change, which is detected. In Weber''s law, to notice a change in stimulus (e.g. brightness or weight), the change must be constant proportion of the original stimulus. Weber''s law states that just noticeable difference is proportional to the magnitude of the initial stimulus. The brain is a percentage of change detector. The differential threshold is the smallest difference needed to differentiate two stimuli for each sense has been studied by using similarly methods to signal detection. For instance, holding an object that weighs 1,2,10, and 11lbs. If one were to hold the lightest object (1lb), and then swap out that object for the 2lb object, one could easily tell that the second object is heavier than the first. There is a 100% weight increase from the first object to the second. However, it becomes more difficult when the difference is a smaller percentage of the initial object''s weight. For example, if one were to hold the 10lb object, and then swap it out and hold the 11lb object, it would be difficult for one to tell which of the two is heavier, because there is only a 10% increase from the first to the second object. This demonstrates that bigger stimuli require a larger difference in order to be noticed. This is Weber''s Law.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law: Weber''s law', 'Fechner formulated several versions of the law, all communicating the same idea. One formulation states: Simple differential sensitivity is inversely proportional to the size of the components of the difference; relative differential sensitivity remains the same regardless of size. What this means is that the perceived change in stimuli is inversely proportional to the initial stimuli. the smallest change in this stimulus that can be perceived. This means that for any Weber''s law always fails at low intensities, near and below the absolute detection threshold, and often also at high intensities, but may be approximately true across a wide middle range of intensities.', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Fechner formulated several versions of the law, all communicating the same idea. One formulation states: Simple differential sensitivity is inversely proportional to the size of the components of the difference; relative differential sensitivity remains the same regardless of size. What this means is that the perceived change in stimuli is inversely proportional to the initial stimuli. the smallest change in this stimulus that can be perceived. This means that for any Weber''s law always fails at low intensities, near and below the absolute detection threshold, and often also at high intensities, but may be approximately true across a wide middle range of intensities.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law: Weber contrast', 'Although Weber''s law includes a statement of the proportionality of a perceived change to initial stimuli, Weber only refers to this as a rule of thumb regarding human perception. It was Fechner who formulated this statement as a mathematical expression referred to as Weber contrast. , we see the proportionality constant in Weber''s law is related to the new constant and the smallest perceptual change, . In Weber contrast this is not the case, so, though the mathematical relationships look similar, they differ in content.', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Although Weber''s law includes a statement of the proportionality of a perceived change to initial stimuli, Weber only refers to this as a rule of thumb regarding human perception. It was Fechner who formulated this statement as a mathematical expression referred to as Weber contrast. , we see the proportionality constant in Weber''s law is related to the new constant and the smallest perceptual change, . In Weber contrast this is not the case, so, though the mathematical relationships look similar, they differ in content.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law: Fechner''s law', 'Fechner noticed in his own studies that different individuals have different sensitivity to certain stimuli. For example, the ability to perceive differences in light intensity could be related to how good that individual''s vision is. He also noted that how the human sensitivity to stimuli changes depends on which sense is affected. He used this to formulate another version of Weber''s law that he named die Maßformel, the "measurement formula". Fechner''s law states that the subjective sensation is proportional to the logarithm of the stimulus intensity. According to this law, human perceptions of sight and sound work as follows: Perceived loudness/brightness is proportional to the logarithm of the actual intensity measured with an accurate nonhuman instrument,', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Fechner noticed in his own studies that different individuals have different sensitivity to certain stimuli. For example, the ability to perceive differences in light intensity could be related to how good that individual''s vision is. He also noted that how the human sensitivity to stimuli changes depends on which sense is affected. He used this to formulate another version of Weber''s law that he named die Maßformel, the "measurement formula". Fechner''s law states that the subjective sensation is proportional to the logarithm of the stimulus intensity. According to this law, human perceptions of sight and sound work as follows: Perceived loudness/brightness is proportional to the logarithm of the actual intensity measured with an accurate nonhuman instrument,');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Weber–Fechner law: Fechner''s law', 'The relationship between stimulus and perception is logarithmic. A logarithmic relationship means that if a stimulus varies as a geometric progression (i.e., multiplied by a fixed factor), the corresponding perception is altered in an arithmetic progression (i.e., in additive constant amounts). For example, if a stimulus is tripled in strength (i.e., 3 × 1), the corresponding perception may be two times as strong as its original value (i.e., 1 + 1). If the stimulus is again tripled in strength (i.e., 3 × 3 × 1), the corresponding perception will be three times as strong as its original value (i.e., 1 + 1 + 1). Hence, for multiplications in stimulus strength, the strength of perception only adds. The mathematical derivations of the torques on a simple beam balance produce a description that is strictly compatible with Weber''s law. An early reference to "Fechner''s... law" was in 1875 by Ludimar Hermann in Elements of Human Physiology.', 'Wikipedia: Weber–Fechner law', 'https://en.wikipedia.org/w/index.php?title=Weber%E2%80%93Fechner_law&oldid=1368615428', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The relationship between stimulus and perception is logarithmic. A logarithmic relationship means that if a stimulus varies as a geometric progression (i.e., multiplied by a fixed factor), the corresponding perception is altered in an arithmetic progression (i.e., in additive constant amounts). For example, if a stimulus is tripled in strength (i.e., 3 × 1), the corresponding perception may be two times as strong as its original value (i.e., 1 + 1). If the stimulus is again tripled in strength (i.e., 3 × 3 × 1), the corresponding perception will be three times as strong as its original value (i.e., 1 + 1 + 1). Hence, for multiplications in stimulus strength, the strength of perception only adds. The mathematical derivations of the torques on a simple beam balance produce a description that is strictly compatible with Weber''s law. An early reference to "Fechner''s... law" was in 1875 by Ludimar Hermann in Elements of Human Physiology.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory', 'Detection theory or signal detection theory is a means to measure the ability to differentiate between information-bearing patterns (called stimulus in living organisms, signal in machines) and random patterns that distract from the information (called noise, consisting of background stimuli and random activity of the detection machine and of the nervous system of the operator). In the field of electronics, signal recovery is the separation of such patterns from a disguising background. According to the theory, there are a number of determiners of how a detecting system will detect a signal, and where its threshold levels will be. The theory can explain how changing the threshold will affect the ability to discern, often exposing how adapted the system is to the task, purpose or goal at which it is aimed. When the detecting system is a human being, characteristics such as experience, expectations, physiological state (e.g. fatigue) and other factors can affect the threshold applied. For instance, a sentry in wartime might be likely to detect fainter stimuli than the same sentry in peacetime due to a lower criterion, however they might also be more likely to treat innocuous stimuli as a threat.', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Detection theory or signal detection theory is a means to measure the ability to differentiate between information-bearing patterns (called stimulus in living organisms, signal in machines) and random patterns that distract from the information (called noise, consisting of background stimuli and random activity of the detection machine and of the nervous system of the operator). In the field of electronics, signal recovery is the separation of such patterns from a disguising background. According to the theory, there are a number of determiners of how a detecting system will detect a signal, and where its threshold levels will be. The theory can explain how changing the threshold will affect the ability to discern, often exposing how adapted the system is to the task, purpose or goal at which it is aimed. When the detecting system is a human being, characteristics such as experience, expectations, physiological state (e.g. fatigue) and other factors can affect the threshold applied. For instance, a sentry in wartime might be likely to detect fainter stimuli than the same sentry in peacetime due to a lower criterion, however they might also be more likely to treat innocuous stimuli as a threat.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory', 'Much of the early work in detection theory was done by radar researchers. By 1954, the theory was fully developed on the theoretical side as described by Peterson, Birdsall and Fox and the foundation for the psychological theory was made by Wilson P. Tanner, David M. Green, and John A. Swets, also in 1954. Detection theory was used in 1966 by John A. Swets and David M. Green for psychophysics. Green and Swets criticized the traditional methods of psychophysics for their inability to discriminate between the real sensitivity of subjects and their (potential) response biases. Detection theory has applications in many fields such as diagnostics of any kind, quality control, telecommunications, and psychology. The concept is similar to the signal-to-noise ratio used in the sciences and confusion matrices used in artificial intelligence. It is also usable in alarm management, where it is important to separate important events from background noise.', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Much of the early work in detection theory was done by radar researchers. By 1954, the theory was fully developed on the theoretical side as described by Peterson, Birdsall and Fox and the foundation for the psychological theory was made by Wilson P. Tanner, David M. Green, and John A. Swets, also in 1954. Detection theory was used in 1966 by John A. Swets and David M. Green for psychophysics. Green and Swets criticized the traditional methods of psychophysics for their inability to discriminate between the real sensitivity of subjects and their (potential) response biases. Detection theory has applications in many fields such as diagnostics of any kind, quality control, telecommunications, and psychology. The concept is similar to the signal-to-noise ratio used in the sciences and confusion matrices used in artificial intelligence. It is also usable in alarm management, where it is important to separate important events from background noise.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory: Psychology', 'Signal detection theory (SDT) is used when psychologists want to measure the way we make decisions under conditions of uncertainty, such as how we would perceive distances in foggy conditions or during eyewitness identification. SDT assumes that the decision maker is not a passive receiver of information, but an active decision-maker who makes difficult perceptual judgments under conditions of uncertainty. In foggy circumstances, we are forced to decide how far away from us an object is, based solely upon visual stimulus which is impaired by the fog. Since the brightness of the object, such as a traffic light, is used by the brain to discriminate the distance of an object, and the fog reduces the brightness of objects, we perceive the object to be much farther away than it actually is (see also decision theory). According to SDT, during eyewitness identifications, witnesses base their decision as to whether a suspect is the culprit or not based on their perceived level of familiarity with the suspect. To apply signal detection theory to a data set where stimuli were either present or absent, and the observer categorized each trial as having the stimulus present or absent, the trials are sorted into one of four categories:', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Signal detection theory (SDT) is used when psychologists want to measure the way we make decisions under conditions of uncertainty, such as how we would perceive distances in foggy conditions or during eyewitness identification. SDT assumes that the decision maker is not a passive receiver of information, but an active decision-maker who makes difficult perceptual judgments under conditions of uncertainty. In foggy circumstances, we are forced to decide how far away from us an object is, based solely upon visual stimulus which is impaired by the fog. Since the brightness of the object, such as a traffic light, is used by the brain to discriminate the distance of an object, and the fog reduces the brightness of objects, we perceive the object to be much farther away than it actually is (see also decision theory). According to SDT, during eyewitness identifications, witnesses base their decision as to whether a suspect is the culprit or not based on their perceived level of familiarity with the suspect. To apply signal detection theory to a data set where stimuli were either present or absent, and the observer categorized each trial as having the stimulus present or absent, the trials are sorted into one of four categories:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory: Psychology', 'Based on the proportions of these types of trials, numerical estimates of sensitivity can be obtained with statistics like the sensitivity index d'' and A'', and response bias can be estimated with statistics like c and β. β is the measure of response bias. Signal detection theory can also be applied to memory experiments, where items are presented on a study list for later testing. A test list is created by combining these ''old'' items with novel, ''new'' items that did not appear on the study list. On each test trial the subject will respond ''yes, this was on the study list'' or ''no, this was not on the study list''. Items presented on the study list are called Targets, and new items are called Distractors. Saying ''Yes'' to a target constitutes a Hit, while saying ''Yes'' to a distractor constitutes a False Alarm.', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Based on the proportions of these types of trials, numerical estimates of sensitivity can be obtained with statistics like the sensitivity index d'' and A'', and response bias can be estimated with statistics like c and β. β is the measure of response bias. Signal detection theory can also be applied to memory experiments, where items are presented on a study list for later testing. A test list is created by combining these ''old'' items with novel, ''new'' items that did not appear on the study list. On each test trial the subject will respond ''yes, this was on the study list'' or ''no, this was not on the study list''. Items presented on the study list are called Targets, and new items are called Distractors. Saying ''Yes'' to a target constitutes a Hit, while saying ''Yes'' to a distractor constitutes a False Alarm.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory: Applications', 'Signal Detection Theory has wide application, both in humans and animals. Topics include memory, stimulus characteristics of schedules of reinforcement, etc.', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Signal Detection Theory has wide application, both in humans and animals. Topics include memory, stimulus characteristics of schedules of reinforcement, etc.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory: Sensitivity or discriminability', 'Conceptually, sensitivity refers to how hard or easy it is to detect that a target stimulus is present from background events. For example, in a recognition memory paradigm, having longer to study to-be-remembered words makes it easier to recognize previously seen or heard words. In contrast, having to remember 30 words rather than 5 makes the discrimination harder. One of the most commonly used statistics for computing sensitivity is the so-called sensitivity index or d''. There are also non-parametric measures, such as the area under the ROC-curve.', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Conceptually, sensitivity refers to how hard or easy it is to detect that a target stimulus is present from background events. For example, in a recognition memory paradigm, having longer to study to-be-remembered words makes it easier to recognize previously seen or heard words. In contrast, having to remember 30 words rather than 5 makes the discrimination harder. One of the most commonly used statistics for computing sensitivity is the so-called sensitivity index or d''. There are also non-parametric measures, such as the area under the ROC-curve.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory: Bias', 'Bias is the extent to which one response is more probable than another, averaging across stimulus-present and stimulus-absent cases. That is, a receiver may be more likely overall to respond that a stimulus is present or more likely overall to respond that a stimulus is not present. Bias is independent of sensitivity. Bias can be desirable if false alarms and misses lead to different costs. For example, if the stimulus is a bomber, then a miss (failing to detect the bomber) may be more costly than a false alarm (reporting a bomber when there is not one), making a liberal response bias desirable. In contrast, giving false alarms too often (crying wolf) may make people less likely to respond, a problem that can be reduced by a conservative response bias.', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Bias is the extent to which one response is more probable than another, averaging across stimulus-present and stimulus-absent cases. That is, a receiver may be more likely overall to respond that a stimulus is present or more likely overall to respond that a stimulus is not present. Bias is independent of sensitivity. Bias can be desirable if false alarms and misses lead to different costs. For example, if the stimulus is a bomber, then a miss (failing to detect the bomber) may be more costly than a false alarm (reporting a bomber when there is not one), making a liberal response bias desirable. In contrast, giving false alarms too often (crying wolf) may make people less likely to respond, a problem that can be reduced by a conservative response bias.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Detection theory: Compressed sensing', 'Another field which is closely related to signal detection theory is called compressed sensing (or compressive sensing). The objective of compressed sensing is to recover high dimensional but with low complexity entities from only a few measurements. Thus, one of the most important applications of compressed sensing is in the recovery of high dimensional signals which are known to be sparse (or nearly sparse) with only a few linear measurements. The number of measurements needed in the recovery of signals is by far smaller than what Nyquist sampling theorem requires provided that the signal is sparse, meaning that it only contains a few non-zero elements. There are different methods of signal recovery in compressed sensing including basis pursuit, expander recovery algorithm, CoSaMP and also fast non-iterative algorithm. In all of the recovery methods mentioned above, choosing an appropriate measurement matrix using probabilistic constructions or deterministic constructions, is of great importance. In other words, measurement matrices must satisfy certain specific conditions such as RIP (Restricted Isometry Property) or Null-Space property in order to achieve robust sparse recovery.', 'Wikipedia: Detection theory', 'https://en.wikipedia.org/w/index.php?title=Detection_theory&oldid=1347392463', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Another field which is closely related to signal detection theory is called compressed sensing (or compressive sensing). The objective of compressed sensing is to recover high dimensional but with low complexity entities from only a few measurements. Thus, one of the most important applications of compressed sensing is in the recovery of high dimensional signals which are known to be sparse (or nearly sparse) with only a few linear measurements. The number of measurements needed in the recovery of signals is by far smaller than what Nyquist sampling theorem requires provided that the signal is sparse, meaning that it only contains a few non-zero elements. There are different methods of signal recovery in compressed sensing including basis pursuit, expander recovery algorithm, CoSaMP and also fast non-iterative algorithm. In all of the recovery methods mentioned above, choosing an appropriate measurement matrix using probabilistic constructions or deterministic constructions, is of great importance. In other words, measurement matrices must satisfy certain specific conditions such as RIP (Restricted Isometry Property) or Null-Space property in order to achieve robust sparse recovery.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system', 'The visual system is the physiological basis of visual perception (the ability to detect and process light). The system detects, transduces and interprets information concerning light within the visible range to construct an image and build a mental model of the surrounding environment. The visual system is associated with the eye and functionally divided into the optical system (including cornea and lens) and the neural system (including the retina and visual cortex). The visual system performs a number of complex tasks based on the image forming functionality of the eye, including the formation of monocular images, the neural mechanisms underlying stereopsis and assessment of distances to (depth perception) and between objects, motion perception, pattern recognition, accurate motor coordination under visual guidance, and colour vision. Together, these facilitate higher order tasks, such as object identification. The neuropsychological side of visual information processing is known as visual perception, an abnormality of which is called visual impairment, and a complete absence of which is called blindness. The visual system also has several non-image forming visual functions, independent of visual perception, including the pupillary light reflex and circadian photoentrainment. This article describes the human visual system, which is representative of mammalian vision, and to a lesser extent the vertebrate visual system.', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The visual system is the physiological basis of visual perception (the ability to detect and process light). The system detects, transduces and interprets information concerning light within the visible range to construct an image and build a mental model of the surrounding environment. The visual system is associated with the eye and functionally divided into the optical system (including cornea and lens) and the neural system (including the retina and visual cortex). The visual system performs a number of complex tasks based on the image forming functionality of the eye, including the formation of monocular images, the neural mechanisms underlying stereopsis and assessment of distances to (depth perception) and between objects, motion perception, pattern recognition, accurate motor coordination under visual guidance, and colour vision. Together, these facilitate higher order tasks, such as object identification. The neuropsychological side of visual information processing is known as visual perception, an abnormality of which is called visual impairment, and a complete absence of which is called blindness. The visual system also has several non-image forming visual functions, independent of visual perception, including the pupillary light reflex and circadian photoentrainment. This article describes the human visual system, which is representative of mammalian vision, and to a lesser extent the vertebrate visual system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system: Optical', 'Together, the cornea and lens refract light into a small image and shine it on the retina. The retina transduces this image into electrical pulses using rods and cones. The optic nerve then carries these pulses through the optic canal. Upon reaching the optic chiasm the nerve fibers decussate (left becomes right). The fibers then branch and terminate in three places.', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Together, the cornea and lens refract light into a small image and shine it on the retina. The retina transduces this image into electrical pulses using rods and cones. The optic nerve then carries these pulses through the optic canal. Upon reaching the optic chiasm the nerve fibers decussate (left becomes right). The fibers then branch and terminate in three places.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system: Neural', 'Most of the optic nerve fibers end in the lateral geniculate nucleus (LGN). Before the LGN forwards the pulses to V1 of the visual cortex (primary) it gauges the range of objects and tags every major object with a velocity tag. These tags predict object movement. V1 performs edge-detection to understand spatial organization (initially, 40 milliseconds in, focusing on even small spatial and color changes. Then, 100 milliseconds in, upon receiving the translated LGN, V2, and V3 info, also begins focusing on global organization). V1 also creates a bottom-up saliency map to guide attention or gaze shift. V2 both forwards (direct and via pulvinar) pulses to V1 and receives them. Pulvinar is responsible for saccade and visual attention. V2 serves much the same function as V1, however, it also handles illusory contours, determining depth by comparing left and right pulses (2D images), and foreground distinguishment. V2 connects to V1 - V5. V3 helps process ''global motion'' (direction and speed) of objects. V3 connects to V1 (weak), V2, and the inferior temporal cortex. V4 recognizes simple shapes, and gets input from V1 (strong), V2, V3, LGN, and pulvinar. V5''s outputs include V4 and its surrounding area, and eye-movement motor cortices (frontal eye-field and lateral intraparietal area).', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Most of the optic nerve fibers end in the lateral geniculate nucleus (LGN). Before the LGN forwards the pulses to V1 of the visual cortex (primary) it gauges the range of objects and tags every major object with a velocity tag. These tags predict object movement. V1 performs edge-detection to understand spatial organization (initially, 40 milliseconds in, focusing on even small spatial and color changes. Then, 100 milliseconds in, upon receiving the translated LGN, V2, and V3 info, also begins focusing on global organization). V1 also creates a bottom-up saliency map to guide attention or gaze shift. V2 both forwards (direct and via pulvinar) pulses to V1 and receives them. Pulvinar is responsible for saccade and visual attention. V2 serves much the same function as V1, however, it also handles illusory contours, determining depth by comparing left and right pulses (2D images), and foreground distinguishment. V2 connects to V1 - V5. V3 helps process ''global motion'' (direction and speed) of objects. V3 connects to V1 (weak), V2, and the inferior temporal cortex. V4 recognizes simple shapes, and gets input from V1 (strong), V2, V3, LGN, and pulvinar. V5''s outputs include V4 and its surrounding area, and eye-movement motor cortices (frontal eye-field and lateral intraparietal area).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system: Neural', 'V5''s functionality is similar to that of the other V''s, however, it integrates local object motion into global motion on a complex level. V6 works in conjunction with V5 on motion analysis. V5 analyzes self-motion, whereas V6 analyzes motion of objects relative to the background. V6''s primary input is V1, with V5 additions. V6 houses the topographical map for vision. V6 outputs to the region directly around it (V6A). V6A has direct connections to arm-moving cortices, including the premotor cortex. The inferior temporal gyrus recognizes complex shapes, objects, and faces or, in conjunction with the hippocampus, creates new memories. The pretectal area is seven unique nuclei. Anterior, posterior and medial pretectal nuclei inhibit pain (indirectly), aid in REM, and aid the accommodation reflex, respectively. The Edinger-Westphal nucleus moderates pupil dilation and aids (since it provides parasympathetic fibers) in convergence of the eyes and lens adjustment. Nuclei of the optic tract are involved in smooth pursuit eye movement and the accommodation reflex, as well as REM. The suprachiasmatic nucleus is the region of the hypothalamus that halts production of melatonin (indirectly) at first light.', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'V5''s functionality is similar to that of the other V''s, however, it integrates local object motion into global motion on a complex level. V6 works in conjunction with V5 on motion analysis. V5 analyzes self-motion, whereas V6 analyzes motion of objects relative to the background. V6''s primary input is V1, with V5 additions. V6 houses the topographical map for vision. V6 outputs to the region directly around it (V6A). V6A has direct connections to arm-moving cortices, including the premotor cortex. The inferior temporal gyrus recognizes complex shapes, objects, and faces or, in conjunction with the hippocampus, creates new memories. The pretectal area is seven unique nuclei. Anterior, posterior and medial pretectal nuclei inhibit pain (indirectly), aid in REM, and aid the accommodation reflex, respectively. The Edinger-Westphal nucleus moderates pupil dilation and aids (since it provides parasympathetic fibers) in convergence of the eyes and lens adjustment. Nuclei of the optic tract are involved in smooth pursuit eye movement and the accommodation reflex, as well as REM. The suprachiasmatic nucleus is the region of the hypothalamus that halts production of melatonin (indirectly) at first light.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system: Structure', 'These are components of the visual pathway, also called the optic pathway, that can be divided into anterior and posterior visual pathways. The anterior visual pathway refers to structures involved in vision before the lateral geniculate nucleus. The posterior visual pathway refers to structures after this point.', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'These are components of the visual pathway, also called the optic pathway, that can be divided into anterior and posterior visual pathways. The anterior visual pathway refers to structures involved in vision before the lateral geniculate nucleus. The posterior visual pathway refers to structures after this point.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system: Eye', 'Light entering the eye is refracted as it passes through the cornea. It then passes through the pupil (controlled by the iris) and is further refracted by the lens. The cornea and lens act together as a compound lens to project an inverted image onto the retina.', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Light entering the eye is refracted as it passes through the cornea. It then passes through the pupil (controlled by the iris) and is further refracted by the lens. The cornea and lens act together as a compound lens to project an inverted image onto the retina.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system: Retina', 'The retina consists of many photoreceptor cells which contain particular protein molecules called opsins. In humans, two types of opsins are involved in conscious vision: rod opsins and cone opsins. (A third type, melanopsin in some retinal ganglion cells (RGC), part of the body clock mechanism, is probably not involved in conscious vision, as these RGC do not project to the lateral geniculate nucleus but to the pretectal olivary nucleus.) An opsin absorbs a photon (a particle of light) and transmits a signal to the cell through a signal transduction pathway, resulting in hyper-polarization of the photoreceptor. Rods and cones differ in function. Rods are found primarily in the periphery of the retina and are used to see at low levels of light. Each human eye contains 120 million rods. Cones are found primarily in the center (or fovea) of the retina. There are three types of cones that differ in the wavelengths of light they absorb; they are usually called short or blue, middle or green, and long or red. Cones mediate day vision and can distinguish color and other features of the visual world at medium and high light levels. Cones are larger and much less numerous than rods (there are 6-7 million of them in each human eye).', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'The retina consists of many photoreceptor cells which contain particular protein molecules called opsins. In humans, two types of opsins are involved in conscious vision: rod opsins and cone opsins. (A third type, melanopsin in some retinal ganglion cells (RGC), part of the body clock mechanism, is probably not involved in conscious vision, as these RGC do not project to the lateral geniculate nucleus but to the pretectal olivary nucleus.) An opsin absorbs a photon (a particle of light) and transmits a signal to the cell through a signal transduction pathway, resulting in hyper-polarization of the photoreceptor. Rods and cones differ in function. Rods are found primarily in the periphery of the retina and are used to see at low levels of light. Each human eye contains 120 million rods. Cones are found primarily in the center (or fovea) of the retina. There are three types of cones that differ in the wavelengths of light they absorb; they are usually called short or blue, middle or green, and long or red. Cones mediate day vision and can distinguish color and other features of the visual world at medium and high light levels. Cones are larger and much less numerous than rods (there are 6-7 million of them in each human eye).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Visual system: Retina', 'In the retina, the photoreceptors synapse directly onto bipolar cells, which in turn synapse onto ganglion cells of the outermost layer, which then conduct action potentials to the brain. A significant amount of visual processing arises from the patterns of communication between neurons in the retina. About 130 million photo-receptors absorb light, yet roughly 1.2 million axons of ganglion cells transmit information from the retina to the brain. The processing in the retina includes the formation of center-surround receptive fields of bipolar and ganglion cells in the retina, as well as convergence and divergence from photoreceptor to bipolar cell. In addition, other neurons in the retina, particularly horizontal and amacrine cells, transmit information laterally (from a neuron in one layer to an adjacent neuron in the same layer), resulting in more complex receptive fields that can be either indifferent to color and sensitive to motion or sensitive to color and indifferent to motion.', 'Wikipedia: Visual system', 'https://en.wikipedia.org/w/index.php?title=Visual_system&oldid=1379042781', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In the retina, the photoreceptors synapse directly onto bipolar cells, which in turn synapse onto ganglion cells of the outermost layer, which then conduct action potentials to the brain. A significant amount of visual processing arises from the patterns of communication between neurons in the retina. About 130 million photo-receptors absorb light, yet roughly 1.2 million axons of ganglion cells transmit information from the retina to the brain. The processing in the retina includes the formation of center-surround receptive fields of bipolar and ganglion cells in the retina, as well as convergence and divergence from photoreceptor to bipolar cell. In addition, other neurons in the retina, particularly horizontal and amacrine cells, transmit information laterally (from a neuron in one layer to an adjacent neuron in the same layer), resulting in more complex receptive fields that can be either indifferent to color and sensitive to motion or sensitive to color and indifferent to motion.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches', 'Bottom-up and top-down are strategies of composition and decomposition in fields as diverse as information processing and ordering knowledge, software, humanistic and scientific theories (see systemics), time management, and organization. In practice they can be seen as a style of thinking, teaching or leadership. A top-down approach (also known as stepwise design and stepwise refinement and in some cases used as a synonym of decomposition) is essentially the breaking down of a system to gain insight into its compositional subsystems in a reverse engineering fashion. In a top-down approach an overview of the system is formulated, specifying but not detailing, any first-level subsystems. Each subsystem is then refined in yet greater detail, sometimes in many additional subsystem levels until the entire specification is reduced to base elements. A top-down model is often specified with the assistance of black boxes, which makes it easier to manipulate. However, black boxes may fail to clarify elementary mechanisms or be detailed enough to realistically validate the model. A top-down approach starts with the big picture, then breaks down into smaller segments.', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Bottom-up and top-down are strategies of composition and decomposition in fields as diverse as information processing and ordering knowledge, software, humanistic and scientific theories (see systemics), time management, and organization. In practice they can be seen as a style of thinking, teaching or leadership. A top-down approach (also known as stepwise design and stepwise refinement and in some cases used as a synonym of decomposition) is essentially the breaking down of a system to gain insight into its compositional subsystems in a reverse engineering fashion. In a top-down approach an overview of the system is formulated, specifying but not detailing, any first-level subsystems. Each subsystem is then refined in yet greater detail, sometimes in many additional subsystem levels until the entire specification is reduced to base elements. A top-down model is often specified with the assistance of black boxes, which makes it easier to manipulate. However, black boxes may fail to clarify elementary mechanisms or be detailed enough to realistically validate the model. A top-down approach starts with the big picture, then breaks down into smaller segments.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches', 'A bottom-up approach is the piecing together of systems to give rise to more complex systems, thus making the original systems subsystems of the emergent system. Bottom-up processing is a type of information processing based on incoming data from the environment to form a perception. From a cognitive psychology perspective, information enters the eyes in one direction (sensory input, or the "bottom") and is then turned into an image by the brain that can be interpreted and recognized as a perception (output that is "built up" from processing to final cognition). In a bottom-up approach the individual base elements of the system are first specified in great detail. These elements are then linked together to form larger subsystems, which then in turn are linked, sometimes in many levels until a complete top-level system is formed. This strategy often resembles a "seed" model by which the beginnings are small but eventually grow in complexity and completeness. But "organic strategies" may result in a tangle of elements and subsystems, developed in isolation and subject to local optimization as opposed to meeting a global purpose.', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'A bottom-up approach is the piecing together of systems to give rise to more complex systems, thus making the original systems subsystems of the emergent system. Bottom-up processing is a type of information processing based on incoming data from the environment to form a perception. From a cognitive psychology perspective, information enters the eyes in one direction (sensory input, or the "bottom") and is then turned into an image by the brain that can be interpreted and recognized as a perception (output that is "built up" from processing to final cognition). In a bottom-up approach the individual base elements of the system are first specified in great detail. These elements are then linked together to form larger subsystems, which then in turn are linked, sometimes in many levels until a complete top-level system is formed. This strategy often resembles a "seed" model by which the beginnings are small but eventually grow in complexity and completeness. But "organic strategies" may result in a tangle of elements and subsystems, developed in isolation and subject to local optimization as opposed to meeting a global purpose.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches: Software development', 'In the software development process, the top-down and bottom-up approaches play a key role. Top-down approaches emphasize planning and a complete understanding of the system. It is inherent that no coding can begin until a sufficient level of detail has been reached in the design of at least some part of the system. Top-down approaches are implemented by attaching the stubs in place of the module. But these delay testing of the ultimate functional units of a system until significant design is complete. Bottom-up emphasizes coding and early testing, which can begin as soon as the first module has been specified. But this approach runs the risk that modules may be coded without having a clear idea of how they link to other parts of the system, and that such linking may not be as easy as first thought. Re-usability of code is one of the main benefits of a bottom-up approach.', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In the software development process, the top-down and bottom-up approaches play a key role. Top-down approaches emphasize planning and a complete understanding of the system. It is inherent that no coding can begin until a sufficient level of detail has been reached in the design of at least some part of the system. Top-down approaches are implemented by attaching the stubs in place of the module. But these delay testing of the ultimate functional units of a system until significant design is complete. Bottom-up emphasizes coding and early testing, which can begin as soon as the first module has been specified. But this approach runs the risk that modules may be coded without having a clear idea of how they link to other parts of the system, and that such linking may not be as easy as first thought. Re-usability of code is one of the main benefits of a bottom-up approach.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches: Software development', 'Top-down design was promoted in the 1970s by IBM researchers Harlan Mills and Niklaus Wirth. Mills developed structured programming concepts for practical use and tested them in a 1969 project to automate the New York Times morgue index. The engineering and management success of this project led to the spread of the top-down approach through IBM and the rest of the computer industry. Among other achievements, Niklaus Wirth, the developer of Pascal programming language, wrote the influential paper Program Development by Stepwise Refinement. Since Niklaus Wirth went on to develop languages such as Modula and Oberon (where one could define a module before knowing about the entire program specification), one can infer that top-down programming was not strictly what he promoted. Top-down methods were favored in software engineering until the late 1980s, and object-oriented programming assisted in demonstrating the idea that both aspects of top-down and bottom-up programming could be used. Modern software design approaches usually combine top-down and bottom-up approaches. Although an understanding of the complete system is usually considered necessary for good design—leading theoretically to a top-down approach—most software projects attempt to make use of existing code to some degree. Pre-existing modules give designs a bottom-up flavor.', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Top-down design was promoted in the 1970s by IBM researchers Harlan Mills and Niklaus Wirth. Mills developed structured programming concepts for practical use and tested them in a 1969 project to automate the New York Times morgue index. The engineering and management success of this project led to the spread of the top-down approach through IBM and the rest of the computer industry. Among other achievements, Niklaus Wirth, the developer of Pascal programming language, wrote the influential paper Program Development by Stepwise Refinement. Since Niklaus Wirth went on to develop languages such as Modula and Oberon (where one could define a module before knowing about the entire program specification), one can infer that top-down programming was not strictly what he promoted. Top-down methods were favored in software engineering until the late 1980s, and object-oriented programming assisted in demonstrating the idea that both aspects of top-down and bottom-up programming could be used. Modern software design approaches usually combine top-down and bottom-up approaches. Although an understanding of the complete system is usually considered necessary for good design—leading theoretically to a top-down approach—most software projects attempt to make use of existing code to some degree. Pre-existing modules give designs a bottom-up flavor.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches: Programming', 'Top-down is a programming style, the mainstay of traditional procedural languages, in which design begins by specifying complex pieces and then dividing them into successively smaller pieces. The technique for writing a program using top-down methods is to write a main procedure that names all the major functions it will need. Later, the programming team looks at the requirements of each of those functions and the process is repeated. These compartmentalized subroutines eventually will perform actions so simple they can be easily and concisely coded. When all the various subroutines have been coded the program is ready for testing. By defining how the application comes together at a high level, lower-level work can be self-contained.', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Top-down is a programming style, the mainstay of traditional procedural languages, in which design begins by specifying complex pieces and then dividing them into successively smaller pieces. The technique for writing a program using top-down methods is to write a main procedure that names all the major functions it will need. Later, the programming team looks at the requirements of each of those functions and the process is repeated. These compartmentalized subroutines eventually will perform actions so simple they can be easily and concisely coded. When all the various subroutines have been coded the program is ready for testing. By defining how the application comes together at a high level, lower-level work can be self-contained.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches: Programming', 'In a bottom-up approach the individual base elements of the system are first specified in great detail. These elements are then linked together to form larger subsystems, which in turn are linked, sometimes at many levels, until a complete top-level system is formed. This strategy often resembles a "seed" model, by which the beginnings are small, but eventually grow in complexity and completeness. Object-oriented programming (OOP) is a paradigm that uses "objects" to design applications and computer programs. In mechanical engineering with software programs such as Pro/ENGINEER, Solidworks, and Autodesk Inventor users can design products as pieces not part of the whole and later add those pieces together to form assemblies like building with Lego. Engineers call this "piece part design".', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In a bottom-up approach the individual base elements of the system are first specified in great detail. These elements are then linked together to form larger subsystems, which in turn are linked, sometimes at many levels, until a complete top-level system is formed. This strategy often resembles a "seed" model, by which the beginnings are small, but eventually grow in complexity and completeness. Object-oriented programming (OOP) is a paradigm that uses "objects" to design applications and computer programs. In mechanical engineering with software programs such as Pro/ENGINEER, Solidworks, and Autodesk Inventor users can design products as pieces not part of the whole and later add those pieces together to form assemblies like building with Lego. Engineers call this "piece part design".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches: Parsing', 'Parsing is the process of analyzing an input sequence (such as that read from a file or a keyboard) in order to determine its grammatical structure. This method is used in the analysis of both natural languages and computer languages, as in a compiler. Bottom-up parsing is parsing strategy that recognizes the text''s lowest-level small details first, before its mid-level structures, and leaves the highest-level overall structure to last. In top-down parsing, on the other hand, one first looks at the highest level of the parse tree and works down the parse tree by using the rewriting rules of a formal grammar.', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Parsing is the process of analyzing an input sequence (such as that read from a file or a keyboard) in order to determine its grammatical structure. This method is used in the analysis of both natural languages and computer languages, as in a compiler. Bottom-up parsing is parsing strategy that recognizes the text''s lowest-level small details first, before its mid-level structures, and leaves the highest-level overall structure to last. In top-down parsing, on the other hand, one first looks at the highest level of the parse tree and works down the parse tree by using the rewriting rules of a formal grammar.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Bottom-up and top-down approaches: Nanotechnology', 'Top-down and bottom-up are two approaches for the manufacture of products. These terms were first applied to the field of nanotechnology by the Foresight Institute in 1989 to distinguish between molecular manufacturing (to mass-produce large atomically precise objects) and conventional manufacturing (which can mass-produce large objects that are not atomically precise). Bottom-up approaches seek to have smaller (usually molecular) components built up into more complex assemblies, while top-down approaches seek to create nanoscale devices by using larger, externally controlled ones to direct their assembly. Certain valuable nanostructures, such as Silicon nanowires, can be fabricated using either approach, with processing methods selected on the basis of targeted applications. A top-down approach often uses the traditional workshop or microfabrication methods where externally controlled tools are used to cut, mill, and shape materials into the desired shape and order. Micropatterning techniques, such as photolithography and inkjet printing belong to this category. Vapor treatment can be regarded as a new top-down secondary approaches to engineer nanostructures.', 'Wikipedia: Bottom-up and top-down approaches', 'https://en.wikipedia.org/w/index.php?title=Bottom-up_and_top-down_approaches&oldid=1380375299', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Top-down and bottom-up are two approaches for the manufacture of products. These terms were first applied to the field of nanotechnology by the Foresight Institute in 1989 to distinguish between molecular manufacturing (to mass-produce large atomically precise objects) and conventional manufacturing (which can mass-produce large objects that are not atomically precise). Bottom-up approaches seek to have smaller (usually molecular) components built up into more complex assemblies, while top-down approaches seek to create nanoscale devices by using larger, externally controlled ones to direct their assembly. Certain valuable nanostructures, such as Silicon nanowires, can be fabricated using either approach, with processing methods selected on the basis of targeted applications. A top-down approach often uses the traditional workshop or microfabrication methods where externally controlled tools are used to cut, mill, and shape materials into the desired shape and order. Micropatterning techniques, such as photolithography and inkjet printing belong to this category. Vapor treatment can be regarded as a new top-down secondary approaches to engineer nanostructures.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Gestalt psychology', 'Gestalt psychology, gestaltism, or configurationism is a school of psychology, and a theory of perception, that emphasizes psychologically processing entire patterns (and "configurations"), not merely individual components of situations or events separately. It emerged in the early twentieth century in Germany and Austria as a rejection of basic principles of Wilhelm Wundt''s and Edward Titchener''s elementalist and structuralist psychology. Gestalt psychology is often associated with the idea that the whole is different from the sum of its parts. In Gestalt theory, information is perceived as wholes rather than disparate parts which are then processed summatively. As used in Gestalt psychology, the German word Gestalt ( gə-SHTA(H)LT; German: [ɡəˈʃtalt]; meaning "form") is interpreted as "pattern" or "configuration". It differs from Gestalt therapy, which is only peripherally linked to Gestalt psychology.', 'Wikipedia: Gestalt psychology', 'https://en.wikipedia.org/w/index.php?title=Gestalt_psychology&oldid=1377498329', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Gestalt psychology, gestaltism, or configurationism is a school of psychology, and a theory of perception, that emphasizes psychologically processing entire patterns (and "configurations"), not merely individual components of situations or events separately. It emerged in the early twentieth century in Germany and Austria as a rejection of basic principles of Wilhelm Wundt''s and Edward Titchener''s elementalist and structuralist psychology. Gestalt psychology is often associated with the idea that the whole is different from the sum of its parts. In Gestalt theory, information is perceived as wholes rather than disparate parts which are then processed summatively. As used in Gestalt psychology, the German word Gestalt ( gə-SHTA(H)LT; German: [ɡəˈʃtalt]; meaning "form") is interpreted as "pattern" or "configuration". It differs from Gestalt therapy, which is only peripherally linked to Gestalt psychology.');
