select 'sensation-perception', 'Gestalt psychology: Origin and history', 'Max Wertheimer, Kurt Koffka, and Wolfgang Köhler founded Gestalt psychology in the early 20th century. The dominant view in psychology at the time was structuralism, exemplified by the work of Hermann von Helmholtz, Wilhelm Wundt, and Edward B. Titchener. Structuralism was rooted firmly in British empiricism and was based on three closely interrelated theories: "atomism", also known as "elementalism", the view that all knowledge, even complex abstract ideas, is built from simple, elementary constituents "sensationalism", the view that the simplest constituents—the atoms of thought—are elementary sense impressions "associationism", the view that more complex ideas arise from the association of simpler ideas. Together, these three theories give rise to the view that the mind constructs all perceptions and abstract thoughts strictly from lower-level sensations, which are related solely by being associated closely in space and time. The Gestaltists took issue with the widespread atomistic view that the aim of psychology should be to break consciousness down into putative basic elements.', 'Wikipedia: Gestalt psychology', 'https://en.wikipedia.org/w/index.php?title=Gestalt_psychology&oldid=1377498329', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'Max Wertheimer, Kurt Koffka, and Wolfgang Köhler founded Gestalt psychology in the early 20th century. The dominant view in psychology at the time was structuralism, exemplified by the work of Hermann von Helmholtz, Wilhelm Wundt, and Edward B. Titchener. Structuralism was rooted firmly in British empiricism and was based on three closely interrelated theories: "atomism", also known as "elementalism", the view that all knowledge, even complex abstract ideas, is built from simple, elementary constituents "sensationalism", the view that the simplest constituents—the atoms of thought—are elementary sense impressions "associationism", the view that more complex ideas arise from the association of simpler ideas. Together, these three theories give rise to the view that the mind constructs all perceptions and abstract thoughts strictly from lower-level sensations, which are related solely by being associated closely in space and time. The Gestaltists took issue with the widespread atomistic view that the aim of psychology should be to break consciousness down into putative basic elements.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'sensation-perception', 'Gestalt psychology: Origin and history', 'In contrast, the Gestalt psychologists believed that breaking psychological phenomena down into smaller parts would not lead to understanding psychology. Instead, they viewed psychological phenomena as organized, structured wholes. They argued that the psychological "whole" has priority and that the "parts" are defined by the structure of the whole, rather than the other way round. Gestalt theories of perception are based on human nature being inclined to understand objects as an entire structure rather than the sum of its parts.', 'Wikipedia: Gestalt psychology', 'https://en.wikipedia.org/w/index.php?title=Gestalt_psychology&oldid=1377498329', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'In contrast, the Gestalt psychologists believed that breaking psychological phenomena down into smaller parts would not lead to understanding psychology. Instead, they viewed psychological phenomena as organized, structured wholes. They argued that the psychological "whole" has priority and that the "parts" are defined by the structure of the whole, rather than the other way round. Gestalt theories of perception are based on human nature being inclined to understand objects as an entire structure rather than the sum of its parts.');
