select 'sensation-perception', 'Gestalt psychology: Origin and history', 'By 1914, the first published references to Gestalt theory could be found in a footnote of Gabriele von Wartensleben''s application of Gestalt theory to personality. She was a student at Frankfurt Academy for Social Sciences, who interacted deeply with Wertheimer and Köhler.', 'Wikipedia: Gestalt psychology', 'https://en.wikipedia.org/w/index.php?title=Gestalt_psychology&oldid=1377498329', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'sensation-perception' and body = 'By 1914, the first published references to Gestalt theory could be found in a footnote of Gabriele von Wartensleben''s application of Gestalt theory to personality. She was a student at Frankfurt Academy for Social Sciences, who interacted deeply with Wertheimer and Köhler.');
